//! Few-cell deconvolution ("EMber-mix", working name): the pooled contacts of k single cells
//! -> k structures and the cell of origin of every contact.
//!
//! Observation model: EMber's mixture (`robust.rs`) with the cell as a further latent
//! variable.  An observed contact is false (rate ε, uniform over the particle pairs of a
//! cell) or true and generated by cell s with probability λ_s ν_cs, landing on pair b with
//! probability φ_sb = f(d_sb) / G_s (f: EMber's contact kernel; G_s = Σ_pairs f in cell s;
//! d_sb averaged over the cell's replicate models through φ):
//!
//! ```text
//! P(true, s | structures) = o λ_s ν_cs (1 - ε) φ_sb / [ o (1 - ε) Σ_s' λ_s' ν_cs' φ_s'b + ε / N_pairs ]
//! ```
//!
//! (o: EMber's evidence odds, the local-support likelihood ratio; λ: mixing weights,
//! learned; ν: per-contact prior over the cells — the symmetry-breaking seed at the first
//! stage, then optionally the 2-D neighbourhood smoothing of the posteriors,
//! `mix_nbr_prior`).
//!
//! M-step: every cell is a group of `n_models` replicate models of the same particle
//! system (one chain per chromosome); the contact restraints (2017 binning of the kept
//! contacts) are shared, and the models of cell s weight restraint b by
//! w_sb = 1 - Π_{contacts c in b} (1 - P(true, s)) (per-model weights, `Weighted2017`), so
//! all cells are annealed in one batched engine call (GPU: one dispatch over all models).
//! There is no nuclear envelope: a cell's compaction comes from its own contacts, the
//! backbone and the excluded volume (as NucDynamics / EMber), and the normaliser G_s of
//! the observation model penalises structures in which pairs without contacts are close.
//!
//! Symmetry breaking (the k cells are exchangeable): `mix_seed` gives the first stage's
//! per-cell weights — "patch": the 2-D contact map of every chromosome pair is cut into
//! random patches (Voronoi cells of random anchor contacts, about `mix_seed_patch` contacts
//! each) and every patch goes to a random cell (contacts closer than `mix_seed_min_sep`
//! stay uniform); "random": every contact to a random cell; "uniform": no seed (only the
//! random start coordinates differ).  `mix_restarts` independent seeds are annealed side
//! by side and the one with the highest mixture likelihood is kept after stage
//! `mix_select_stage`.
//!
//! Staged commitment (`mix_commit` τ, from stage `mix_commit_stage`): a contact whose
//! cell posterior reaches τ is restrained in that cell only; the others stay soft (or are
//! dropped, `mix_commit_drop`, and re-admitted at `mix_readmit_stage`).
//!
//! Everything else is EMber's: the isolation filter (on the pooled contacts), the particle
//! grid of each stage (from the pooled contacts), removal of contacts violated by >= 6
//! radii in their closest cell before stages < 0.5 Mb, the schedule, EM twice per stage,
//! refinement and sampling.
//!
//! Output: models cell-major (cell s = models s n_models .. (s + 1) n_models); per input
//! contact P(cell s | true) for every cell and P(true), from a final E-step on the final
//! structures over *all* input contacts (filtered ones included, so every contact gets a
//! cell).

use crate::contacts::{contact_count, Contact, ContactDict, Structure};
use crate::dynamics::{NoContact, RestraintForm, System, V3};
use crate::params::{anneal_schedule, Params};
use crate::pipeline::{Input, Output, StageEngine, StageLog};
use crate::protocol2017::{backbone_restraints, calc_particles, interpolate, remove_isolated_contacts, start_coords};
use crate::restraints::{Restraint, RestraintSet};
use crate::robust::{force_constant, kernel_sum, set_weights, split_schedule, EmData, EmLog, Kernel};
use crate::rng::Rng;
use crate::support::{support_evidence, SupportParams};
use rayon::prelude::*;
use std::collections::BTreeMap;
use std::time::Instant;

/// One input contact in canonical orientation.
#[derive(Clone, Copy, Debug)]
pub struct MixContact {
    pub ca: u32,
    pub pa: i64,
    pub cb: u32,
    pub pb: i64,
    pub row: u32,
}

impl MixContact {
    /// Genomic separation (bp; trans: i64::MAX).
    pub fn sep(&self) -> i64 {
        if self.ca == self.cb {
            (self.pb - self.pa).abs()
        } else {
            i64::MAX
        }
    }
}

pub fn prepare_contacts(input: &Input) -> Vec<MixContact> {
    (0..input.chr_a.len())
        .map(|i| {
            let (mut ca, mut pa, mut cb, mut pb) = (input.chr_a[i], input.pos_a[i], input.chr_b[i], input.pos_b[i]);
            if (ca, pa) > (cb, pb) {
                std::mem::swap(&mut ca, &mut cb);
                std::mem::swap(&mut pa, &mut pb);
            }
            MixContact { ca, pa, cb, pb, row: i as u32 }
        })
        .collect()
}

/// Contact dictionary of the kept contacts (`Contact::number` = index into `contacts`).
fn base_dict(contacts: &[MixContact], keep: &[bool]) -> ContactDict {
    let mut d: ContactDict = BTreeMap::new();
    for (k, c) in contacts.iter().enumerate() {
        if keep[k] {
            d.entry((c.ca, c.cb)).or_default().push(Contact { pos_a: c.pa, pos_b: c.pb, ambig: 0, number: k as u32 });
        }
    }
    d
}

/// Kept contacts binned on the particles of `st` (2017 convention: an end at p goes to the
/// first particle at or after p; ends beyond the last particle drop the contact): one bin
/// per particle pair, sorted.
#[derive(Clone, Debug, Default)]
pub struct Bins {
    pub pairs: Vec<[u32; 2]>,
    /// contacts of bin b: `contacts[off[b]..off[b + 1]]` (indices into the contact list)
    pub off: Vec<u32>,
    pub contacts: Vec<u32>,
}

impl Bins {
    pub fn n(&self) -> usize {
        self.pairs.len()
    }
    pub fn n_contacts(&self) -> usize {
        self.contacts.len()
    }
}

pub fn bin_contacts(contacts: &[MixContact], keep: &[bool], st: &Structure) -> Bins {
    let mut map: BTreeMap<(u32, u32), Vec<u32>> = BTreeMap::new();
    for (k, c) in contacts.iter().enumerate() {
        if !keep[k] {
            continue;
        }
        let (Some(sa), Some(sb)) = (st.chrom_slot(c.ca), st.chrom_slot(c.cb)) else {
            continue;
        };
        let (spa, spb) = (&st.seq_pos[sa], &st.seq_pos[sb]);
        let j = spa.partition_point(|&x| x < c.pa as i32 as i64);
        let l = spb.partition_point(|&x| x < c.pb as i32 as i64);
        if j >= spa.len() || l >= spb.len() {
            continue;
        }
        let (i, j) = ((st.offsets[sa] + j) as u32, (st.offsets[sb] + l) as u32);
        map.entry((i.min(j), i.max(j))).or_default().push(k as u32);
    }
    let mut b = Bins { off: vec![0], ..Default::default() };
    for ((i, j), v) in map {
        b.pairs.push([i, j]);
        b.contacts.extend(v);
        b.off.push(b.contacts.len() as u32);
    }
    b
}

/// 2-D neighbours of every contact (hickit's imputation neighbourhood, as
/// `diploid::neighbour_prior`): the `max_nei` nearest contacts of the same chromosome pair
/// with both ends within `radius` (Chebyshev distance d), weight 1 / (d / span + 0.001) with
/// span the contact's own separation (trans: `radius`; at least `min_span`).
pub fn neighbour_lists(contacts: &[MixContact], radius: i64, min_span: i64, max_nei: usize) -> Vec<Vec<(u32, f32)>> {
    let n = contacts.len();
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by_key(|&k| (contacts[k].ca, contacts[k].cb, contacts[k].pa, contacts[k].pb));
    let mut gs = vec![0usize; n];
    let mut ge = vec![0usize; n];
    let mut rank = vec![0usize; n];
    let mut s = 0;
    while s < n {
        let key = (contacts[order[s]].ca, contacts[order[s]].cb);
        let mut e = s;
        while e < n && (contacts[order[e]].ca, contacts[order[e]].cb) == key {
            e += 1;
        }
        for (q, &k) in order[s..e].iter().enumerate() {
            gs[k] = s;
            ge[k] = e;
            rank[k] = s + q;
        }
        s = e;
    }
    (0..n)
        .into_par_iter()
        .map(|k| {
            let c = &contacts[k];
            let mut best: Vec<(i64, u32)> = Vec::with_capacity(max_nei + 1);
            let worst = |b: &Vec<(i64, u32)>| b.iter().map(|x| x.0).max().unwrap_or(i64::MAX);
            let consider = |j: usize, best: &mut Vec<(i64, u32)>| -> bool {
                let o = &contacts[j];
                let y = (o.pa - c.pa).abs();
                if y > radius || (best.len() >= max_nei && y > worst(best)) {
                    return false;
                }
                let z = (o.pb - c.pb).abs();
                if z <= radius {
                    let d = y.max(z);
                    if best.len() < max_nei {
                        best.push((d, j as u32));
                    } else if d < worst(best) {
                        let wi = (0..best.len()).max_by_key(|&i| best[i].0).unwrap();
                        best[wi] = (d, j as u32);
                    }
                }
                true
            };
            let r0 = rank[k];
            let mut q = r0;
            while q > gs[k] {
                q -= 1;
                if !consider(order[q], &mut best) {
                    break;
                }
            }
            for &j in &order[r0 + 1..ge[k]] {
                if !consider(j, &mut best) {
                    break;
                }
            }
            let span = if c.ca != c.cb { radius } else { (c.pb - c.pa).abs() }.max(min_span) as f64;
            best.into_iter().map(|(d, j)| (j, (1.0 / (d as f64 / span + 1e-3)) as f32)).collect()
        })
        .collect()
}

/// Symmetry-breaking seed: per contact a prior over the k cells (row-major, k values per
/// contact), for restart `restart`.
pub fn seed_prior(contacts: &[MixContact], keep: &[bool], k: usize, p: &Params, restart: usize) -> Vec<f64> {
    let n = contacts.len();
    let uni = 1.0 / k as f64;
    let mut nu = vec![uni; n * k];
    let mut rng = Rng::from_keys(&[p.seed, 0x6d69_78u64, restart as u64]);
    let hard = |nu: &mut [f64], c: usize, s: usize| {
        for x in 0..k {
            nu[c * k + x] = if x == s { 1.0 } else { 0.0 };
        }
    };
    let eligible = |c: &MixContact| c.sep() >= p.mix_seed_min_sep;
    match p.mix_seed.as_str() {
        "uniform" => {}
        "random" => {
            for (i, c) in contacts.iter().enumerate() {
                if keep[i] && eligible(c) {
                    let s = ((rng.uniform() * k as f64) as usize).min(k - 1);
                    hard(&mut nu, i, s);
                }
            }
        }
        "tri" => {
            let tp = crate::mixseed::TriParams {
                iters: p.mix_tri_iters,
                t0: p.mix_tri_t0,
                t1: p.mix_tri_t1,
                damping: 0.5,
                learn_pi: p.mix_learn_pi,
            };
            return crate::mixseed::triangle_seed(
                contacts,
                keep,
                k,
                p.mix_tri_res,
                p.mix_seed_min_sep,
                p.mix_tri_max,
                &tp,
                crate::rng::hash_keys(&[p.seed, restart as u64]),
            );
        }
        "patch" => {
            // per chromosome pair: anchors = a random subset of the eligible kept contacts (one per
            // `mix_seed_patch` on average, at least k), each with a random cell; every eligible
            // contact takes the cell of its nearest anchor (Chebyshev distance in 2-D)
            let mut by_pair: BTreeMap<(u32, u32), Vec<usize>> = BTreeMap::new();
            for (i, c) in contacts.iter().enumerate() {
                if keep[i] && eligible(c) {
                    by_pair.entry((c.ca, c.cb)).or_default().push(i);
                }
            }
            for (_, idx) in by_pair {
                let na = (idx.len() as f64 / p.mix_seed_patch.max(1.0)).ceil().max(1.0) as usize;
                let mut anchors: Vec<(i64, i64, usize)> = Vec::with_capacity(na);
                for _ in 0..na {
                    let a = idx[((rng.uniform() * idx.len() as f64) as usize).min(idx.len() - 1)];
                    let s = ((rng.uniform() * k as f64) as usize).min(k - 1);
                    anchors.push((contacts[a].pa, contacts[a].pb, s));
                }
                anchors.sort_unstable();
                for &i in &idx {
                    let c = &contacts[i];
                    // nearest anchor: scan outwards from pa (anchors sorted by pa)
                    let r0 = anchors.partition_point(|x| x.0 < c.pa);
                    let mut best = (i64::MAX, 0usize);
                    let look = |q: usize, best: &mut (i64, usize)| -> bool {
                        let (ya, yb, s) = anchors[q];
                        let dy = (ya - c.pa).abs();
                        if dy >= best.0 {
                            return false;
                        }
                        let d = dy.max((yb - c.pb).abs());
                        if d < best.0 {
                            *best = (d, s);
                        }
                        true
                    };
                    for q in r0..anchors.len() {
                        if !look(q, &mut best) {
                            break;
                        }
                    }
                    for q in (0..r0).rev() {
                        if !look(q, &mut best) {
                            break;
                        }
                    }
                    hard(&mut nu, i, best.1);
                }
            }
        }
        _ => {}
    }
    nu
}

/// Result of one E-step + M-step of the mixture on one restart group.
pub struct MixEm {
    /// [cell][bin] restraint weight
    pub w: Vec<Vec<f64>>,
    /// per contact of the bins (bin order): P(true) and P(cell | true) (k values)
    pub r_true: Vec<f64>,
    pub post: Vec<f64>,
    pub lambda: Vec<f64>,
    pub eps: f64,
    pub s: f64,
    pub log: EmLog,
}

/// E-step + M-step on fixed distances.  `data`: the models of one restart group (cell-major,
/// `m` per cell); `odds`: per contact (contact-list index); `nu`: prior over the cells per
/// contact (k per contact-list index); `lambda`: mixing weights.
#[allow(clippy::too_many_arguments)]
pub fn em_update_mix(
    data: &EmData,
    bins: &Bins,
    odds: &[f64],
    nu: &[f64],
    lambda: &[f64],
    k: usize,
    m: usize,
    kern: &Kernel,
    p: &Params,
    eps0: f64,
    s0: f64,
    groups: Option<&[u32]>,
) -> MixEm {
    let t0 = Instant::now();
    let u = 1.0 / data.n_pairs.max(1.0);
    let nb = bins.n();
    let ncon = bins.n_contacts().max(1) as f64;
    // φ[s][b] = mean over the cell's models of f(d) / G
    let phi_of = |kk: &Kernel, s: f64| -> (Vec<Vec<f64>>, f64) {
        let g: Vec<f64> = data.hist.iter().map(|h| kernel_sum(kk, h, data.bin, data.n_pairs, s).max(1e-300)).collect();
        let phi: Vec<Vec<f64>> = (0..k)
            .map(|c| {
                let mut row = vec![0.0; nb];
                for r in 0..m {
                    let mi = c * m + r;
                    for (b, x) in row.iter_mut().enumerate() {
                        *x += kk.f(data.dist[mi][b], s) / g[mi] / m as f64;
                    }
                }
                row
            })
            .collect();
        (phi, g.iter().sum::<f64>() / g.len().max(1) as f64)
    };
    // Σ_s λ_s ν_cs φ_sb of contact c in bin b
    let mixsum = |phi: &[Vec<f64>], b: usize, c: usize| -> f64 { (0..k).map(|s| lambda[s] * nu[c * k + s] * phi[s][b]).sum() };
    let fit = |phi: &[Vec<f64>]| -> (f64, f64) {
        let mut eps = eps0;
        if p.robust_learn_eps {
            for _ in 0..200 {
                let fsum: f64 = (0..nb)
                    .into_par_iter()
                    .map(|b| {
                        let mut f = 0.0;
                        for &c in &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize] {
                            let a = odds[c as usize] * (1.0 - eps) * mixsum(phi, b, c as usize);
                            f += if a <= 0.0 { 1.0 } else { eps * u / (a + eps * u) };
                        }
                        f
                    })
                    .sum();
                let new = (fsum / ncon).clamp(p.robust_eps_min, p.robust_eps_max);
                let done = (new - eps).abs() < 1e-8;
                eps = new;
                if done {
                    break;
                }
            }
        }
        let ll: f64 = (0..nb)
            .into_par_iter()
            .map(|b| {
                let mut l = 0.0;
                for &c in &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize] {
                    let o = odds[c as usize];
                    let rho = o * (1.0 - eps) / (o * (1.0 - eps) + eps);
                    l += ((rho * mixsum(phi, b, c as usize) + (1.0 - rho) * u) / u).ln();
                }
                l
            })
            .sum();
        (ll / ncon, eps)
    };
    let grid: Vec<f64> = if p.robust_learn_s { p.robust_s_grid.clone() } else { vec![s0] };
    let d0s: Vec<f64> = if p.robust_d0_grid.is_empty() { vec![kern.d0] } else { p.robust_d0_grid.clone() };
    let mut best: Option<(f64, f64, f64, f64)> = None;
    for (&s, &d0) in grid.iter().flat_map(|s| d0s.iter().map(move |d| (s, d))) {
        let kk = Kernel { d0, ..*kern };
        let (phi, _) = phi_of(&kk, s);
        let (ll, eps) = fit(&phi);
        if best.is_none_or(|bb| ll > bb.0) {
            best = Some((ll, s, eps, d0));
        }
    }
    let (ll, s, eps, d0) = best.unwrap();
    let kk = Kernel { d0, ..*kern };
    let (phi, g_mean) = phi_of(&kk, s);
    // group posteriors (must-link groups of contacts, `mix_group_radius`): every member of a group
    // comes from the same cell, so the group's cell posterior is λ_s Π_members [ν_cs (o (1 - ε) φ_sb + ε u)]
    let gpost: Option<Vec<f64>> = groups.map(|gr| {
        let ng = bins.contacts.iter().filter_map(|&c| (gr[c as usize] != u32::MAX).then_some(gr[c as usize] as usize + 1)).max().unwrap_or(0);
        let terms: Vec<Vec<(u32, Vec<f64>)>> = (0..nb)
            .into_par_iter()
            .map(|b| {
                bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize]
                    .iter()
                    .filter(|&&c| gr[c as usize] != u32::MAX)
                    .map(|&c| {
                        let c = c as usize;
                        let o = odds[c];
                        (gr[c], (0..k).map(|x| nu[c * k + x].max(1e-300).ln() + (o * (1.0 - eps) * phi[x][b] + eps * u).ln()).collect())
                    })
                    .collect()
            })
            .collect();
        let mut sums = vec![0.0f64; ng * k];
        for t in terms.into_iter().flatten() {
            for x in 0..k {
                sums[t.0 as usize * k + x] += t.1[x];
            }
        }
        for gi in 0..ng {
            let row = &mut sums[gi * k..(gi + 1) * k];
            let mx = (0..k).map(|x| lambda[x].max(1e-300).ln() + row[x]).fold(f64::NEG_INFINITY, f64::max);
            let mut tot = 0.0;
            for x in 0..k {
                row[x] = (lambda[x].max(1e-300).ln() + row[x] - mx).exp();
                tot += row[x];
            }
            for x in 0..k {
                row[x] /= tot;
            }
        }
        sums
    });
    // responsibilities, bin by bin
    let per_bin: Vec<(Vec<f64>, Vec<f64>, Vec<f64>)> = (0..nb)
        .into_par_iter()
        .map(|b| {
            let cs = &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize];
            let mut none = vec![1.0f64; k];
            let mut sum = vec![0.0f64; k];
            let mut rt = Vec::with_capacity(cs.len());
            let mut post = Vec::with_capacity(cs.len() * k);
            for &c in cs {
                let c = c as usize;
                let o = odds[c];
                if let (Some(gp), Some(gr)) = (gpost.as_ref(), groups) {
                    if gr[c] != u32::MAX {
                        let g = gr[c] as usize;
                        let mut tt = 0.0;
                        for x in 0..k {
                            let a = o * (1.0 - eps) * phi[x][b];
                            let r = gp[g * k + x] * if a <= 0.0 { 0.0 } else { a / (a + eps * u) };
                            none[x] *= 1.0 - r;
                            sum[x] += r;
                            tt += r;
                            post.push(gp[g * k + x]);
                        }
                        rt.push(tt);
                        continue;
                    }
                }
                let a: Vec<f64> = (0..k).map(|x| o * lambda[x] * nu[c * k + x] * (1.0 - eps) * phi[x][b]).collect();
                let at: f64 = a.iter().sum();
                let den = at + eps * u;
                rt.push(if at <= 0.0 { 0.0 } else { at / den });
                for x in 0..k {
                    let r = if at <= 0.0 { 0.0 } else { a[x] / den };
                    none[x] *= 1.0 - r;
                    sum[x] += r;
                    post.push(if at > 0.0 { a[x] / at } else { nu[c * k + x] });
                }
            }
            let n = cs.len().max(1) as f64;
            let w: Vec<f64> = (0..k)
                .map(|x| (if p.robust_count_combine { 1.0 - none[x] } else { sum[x] / n }).max(p.robust_w_floor))
                .collect();
            (w, rt, post)
        })
        .collect();
    let mut w = vec![vec![0.0; nb]; k];
    let mut r_true = Vec::with_capacity(bins.n_contacts());
    let mut post = Vec::with_capacity(bins.n_contacts() * k);
    for (b, (wb, rt, pb)) in per_bin.into_iter().enumerate() {
        for x in 0..k {
            w[x][b] = wb[x];
        }
        r_true.extend(rt);
        post.extend(pb);
    }
    // mixing weights
    let mut lam = lambda.to_vec();
    if p.mix_learn_pi {
        let mut acc = vec![0.0; k];
        for (q, &rt) in r_true.iter().enumerate() {
            for x in 0..k {
                acc[x] += rt * post[q * k + x];
            }
        }
        let tot: f64 = acc.iter().sum();
        if tot > 0.0 {
            for x in 0..k {
                lam[x] = (acc[x] / tot).max(p.mix_pi_floor);
            }
            let t2: f64 = lam.iter().sum();
            for x in lam.iter_mut() {
                *x /= t2;
            }
        }
    }
    let nq = r_true.len().max(1) as f64;
    // marginal log-likelihood with a uniform cell prior (λ only)
    let ll_marg: f64 = (0..nb)
        .into_par_iter()
        .map(|b| {
            let mut l = 0.0;
            for &c in &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize] {
                let o = odds[c as usize];
                let rho = o * (1.0 - eps) / (o * (1.0 - eps) + eps);
                let mx: f64 = (0..k).map(|x| lam[x] * phi[x][b]).sum();
                l += ((rho * mx + (1.0 - rho) * u) / u).ln();
            }
            l
        })
        .sum::<f64>()
        / ncon;
    let mean_w = r_true.iter().sum::<f64>() / nq;
    let low = r_true.iter().filter(|&&x| x < 0.5).count() as f64 / nq;
    let conf = (0..r_true.len()).filter(|&q| post[q * k..(q + 1) * k].iter().cloned().fold(0.0, f64::max) >= 0.9).count();
    let log = EmLog {
        segment: 0,
        eps,
        s,
        d0,
        loglik: ll,
        mean_w,
        frac_low: low,
        prox_frac: g_mean * u,
        capture_q: (1.0 - eps) * nq / g_mean,
        n_particles: data.n_particles,
        seconds: t0.elapsed().as_secs_f64(),
        phase_confident: Some(conf as f64 / nq),
        n_ambiguous: Some(r_true.len()),
        ll_marginal: Some(ll_marg),
    };
    MixEm { w, r_true, post, lambda: lam, eps, s, log }
}

/// 2-D neighbourhood smoothing of the cell posteriors: ν_c ∝ (pseudo / k + Σ_j w_cj post_j)^γ.
fn smooth_prior(nbr: &[Vec<(u32, f32)>], post: &[Option<Vec<f64>>], k: usize, gamma: f64, pseudo: f64) -> Vec<f64> {
    let n = nbr.len();
    let rows: Vec<Vec<f64>> = (0..n)
        .into_par_iter()
        .map(|c| {
            let mut v = vec![pseudo / k as f64; k];
            for &(j, w) in &nbr[c] {
                if let Some(pj) = &post[j as usize] {
                    for x in 0..k {
                        v[x] += w as f64 * pj[x];
                    }
                }
            }
            let mut tot = 0.0;
            for x in v.iter_mut() {
                *x = x.powf(gamma);
                tot += *x;
            }
            v.iter().map(|x| x / tot).collect()
        })
        .collect();
    rows.into_iter().flatten().collect()
}

fn log(p: &Params, msg: &str) {
    if p.verbose {
        eprintln!("[uchrom_recon] {msg}");
    }
}

fn centre(coords: &mut [Vec<V3>]) {
    for c in coords.iter_mut() {
        let k = c.len() as f64;
        let mut m = [0.0; 3];
        for q in c.iter() {
            for x in 0..3 {
                m[x] += q[x];
            }
        }
        for q in c.iter_mut() {
            for x in 0..3 {
                q[x] -= m[x] / k;
            }
        }
    }
}

/// Distance of contact c in every model (ends interpolated on the chains).
fn contact_dists(c: &MixContact, st: &Structure) -> Vec<f64> {
    let (Some(sa), Some(sb)) = (st.chrom_slot(c.ca), st.chrom_slot(c.cb)) else {
        return vec![f64::INFINITY; st.n_models()];
    };
    (0..st.n_models())
        .map(|m| {
            let a = interpolate(c.pa as i32 as i64, &st.seq_pos[sa], st.chrom_coords(m, sa));
            let b = interpolate(c.pb as i32 as i64, &st.seq_pos[sb], st.chrom_coords(m, sb));
            ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
        })
        .collect()
}

/// Restraint set: backbone, then one restraint per bin; bounds from the expected count of the
/// bin in its most likely cell (`counts`), as the 2017 power law.
fn restraint_set(backbone: Vec<Restraint>, bins: &Bins, counts: &[f64], p: &Params) -> (RestraintSet, usize) {
    let (exp32, lo32, hi32) = (p.dist_power_law as f32, p.contact_dist_lower as f32 as f64, p.contact_dist_upper as f32 as f64);
    let nb = backbone.len();
    let mut rest = backbone;
    for (b, pr) in bins.pairs.iter().enumerate() {
        let mut cnt = counts[b].round().max(1.0) as u32;
        if p.robust_count_cap > 0 {
            cnt = cnt.min(p.robust_count_cap);
        }
        let dist = (1.0f32 * (cnt as f32).powf(exp32)) as f64;
        rest.push(Restraint { i: pr[0], j: pr[1], lo: dist * lo32, hi: dist * hi32, ambig: 0, weight: 1.0 });
    }
    let groups: Vec<u32> = (0..=rest.len() as u32).collect();
    (RestraintSet { rest, groups, n_contacts: bins.n_contacts() }, nb)
}

/// Per model of a restart group: the weights of its cell (`w[cell]`), cell-major.
fn model_rows(w: &[Vec<f64>], m: usize) -> Vec<Vec<f64>> {
    w.iter().flat_map(|row| std::iter::repeat_n(row.clone(), m)).collect()
}

/// Prior-only weights (stage before the first EM update): every contact true, cell from `nu`.
fn prior_weights(bins: &Bins, nu: &[f64], k: usize, p: &Params) -> Vec<Vec<f64>> {
    let mut w = vec![vec![0.0; bins.n()]; k];
    for b in 0..bins.n() {
        let cs = &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize];
        for x in 0..k {
            let (mut none, mut sum) = (1.0f64, 0.0f64);
            for &c in cs {
                let r = nu[c as usize * k + x];
                none *= 1.0 - r;
                sum += r;
            }
            let n = cs.len().max(1) as f64;
            w[x][b] = (if p.robust_count_combine { 1.0 - none } else { sum / n }).max(p.robust_w_floor);
        }
    }
    w
}

/// Expected count of every bin in its most likely cell (Σ over its contacts of P(true, s), max
/// over s; prior-only: Σ ν).
fn bin_counts(bins: &Bins, k: usize, resp: &dyn Fn(usize, usize) -> f64) -> Vec<f64> {
    (0..bins.n())
        .map(|b| {
            let cs = &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize];
            (0..k).map(|x| cs.iter().map(|&c| resp(c as usize, x)).sum::<f64>()).fold(0.0, f64::max)
        })
        .collect()
}

/// The few-cell deconvolution (protocol `robust` with `mix_cells` >= 2, haploid input).
pub fn calc_genome_structure(input: &Input, p: &Params, engine: &mut dyn StageEngine) -> Result<Output, String> {
    calc_with_prior(input, p, engine, None)
}

/// As `calc_genome_structure`; `prior`: a given per-contact prior over the cells (k values per
/// input row, rows summing to 1) used as the seed of every restart instead of `mix_seed`
/// (oracle / reference-based seeding).
pub fn calc_with_prior(input: &Input, p: &Params, engine: &mut dyn StageEngine, prior: Option<&[f64]>) -> Result<Output, String> {
    p.validate()?;
    let t0 = Instant::now();
    let k = p.mix_cells;
    if k < 2 {
        return Err("mix: mix_cells must be >= 2".into());
    }
    if let Some(dip) = &input.dip {
        return crate::mixdip::calc_diploid_mix(input, dip, p, engine, prior);
    }
    let m = p.n_models;
    let n_restarts = p.mix_restarts.max(1);
    let n_input = input.chr_a.len();
    let contacts = prepare_contacts(input);
    let mut chroms: Vec<u32> = input.chr_a.iter().chain(input.chr_b).copied().collect();
    chroms.sort_unstable();
    chroms.dedup();
    log(p, &format!("mix: {} pooled contacts, {k} cells x {m} models, {n_restarts} restart(s)", contacts.len()));
    let kern = Kernel::from_params(p);
    let kern_reach = Kernel { d0: p.robust_d0_grid.iter().cloned().fold(p.robust_d0, f64::max), ..kern };
    let s_max = p.robust_s_grid.iter().cloned().fold(p.robust_s, f64::max);
    let last = *p.particle_sizes.last().unwrap();
    // evidence odds per contact (local support on the pooled contacts) x given prior
    let odds_all: Vec<f64> = if p.robust_support_rel > 0.0 {
        let sp = SupportParams { window: p.robust_support_rel * last, seed: p.seed, ..Default::default() };
        let s = support_evidence(input.chr_a, input.pos_a, input.chr_b, input.pos_b, &sp);
        let mut lr = s.lr;
        if let Some(x) = input.prior_lr {
            for (a, b) in lr.iter_mut().zip(x) {
                *a *= b;
            }
        }
        contacts.iter().map(|c| lr[c.row as usize]).collect()
    } else {
        contacts.iter().map(|c| input.prior_lr.map(|x| x[c.row as usize]).unwrap_or(1.0)).collect()
    };
    // isolation filter on the pooled contacts
    let mut keep = {
        let mut d = base_dict(&contacts, &vec![true; contacts.len()]);
        log(p, &format!("total number of contacts = {}", contact_count(&d)));
        remove_isolated_contacts(&mut d, p.isolation_threshold_cis, p.isolation_pos_error);
        let mut kp = vec![false; contacts.len()];
        for v in d.values() {
            for c in v {
                kp[c.number as usize] = true;
            }
        }
        log(p, &format!("contacts after removing isolated = {}", contact_count(&d)));
        kp
    };
    let nbr = if p.mix_nbr_prior > 0.0 {
        let ts = Instant::now();
        let v = neighbour_lists(&contacts, p.mix_nbr_radius, 50_000, p.mix_nbr_max);
        log(p, &format!("2-D neighbour lists in {:.2} s", ts.elapsed().as_secs_f64()));
        Some(v)
    } else {
        None
    };
    let tri_links = if p.mix_tri_prior > 0.0 {
        let v = crate::mixseed::trans_triangle_links(&contacts, &keep, p.mix_tri_res);
        let nl: usize = v.1.iter().filter(|x| !x.is_empty()).count();
        log(p, &format!("trans-triangle links: {} trans edges, {nl} in closed triangles", v.1.len()));
        Some(v)
    } else {
        None
    };
    let groups: Option<Vec<u32>> = if p.mix_group_radius > 0 {
        let g = crate::mixseed::blob_groups(&contacts, &keep, p.mix_group_radius, p.mix_seed_min_sep, p.mix_group_tri_min, p.mix_tri_res);
        let ng = g.iter().filter(|&&x| x != u32::MAX).map(|&x| x as usize + 1).max().unwrap_or(0);
        log(p, &format!("must-link groups: {ng} groups over {} contacts", g.iter().filter(|&&x| x != u32::MAX).count()));
        Some(g)
    } else {
        None
    };
    // per restart: prior over the cells, mixing weights, EM state, last posteriors per contact
    let mut nu: Vec<Vec<f64>> = match prior {
        Some(pr) => {
            if pr.len() != n_input * k {
                return Err("mix prior: k values per contact".into());
            }
            let mut v = vec![0.0; n_input * k];
            for c in &contacts {
                let r = c.row as usize;
                v[r * k..(r + 1) * k].copy_from_slice(&pr[r * k..(r + 1) * k]);
            }
            vec![v; n_restarts]
        }
        None if p.mix_seed == "group" => {
            // the largest must-link groups (by contacts) seeded round-robin to the cells, the rest uniform
            let gr = groups.as_ref().ok_or("mix_seed \"group\" needs mix_group_radius > 0")?;
            let ng = gr.iter().filter(|&&x| x != u32::MAX).map(|&x| x as usize + 1).max().unwrap_or(0);
            let mut size = vec![0usize; ng];
            for &x in gr.iter() {
                if x != u32::MAX {
                    size[x as usize] += 1;
                }
            }
            let mut order: Vec<usize> = (0..ng).collect();
            order.sort_by_key(|&x| std::cmp::Reverse(size[x]));
            let mut cellof = vec![usize::MAX; ng];
            for (j, &x) in order.iter().take(p.mix_group_seed_n).enumerate() {
                cellof[x] = j % k;
            }
            let conf = p.mix_group_seed_conf;
            let mut v = vec![1.0 / k as f64; n_input * k];
            for (i, &x) in gr.iter().enumerate() {
                if x != u32::MAX && cellof[x as usize] != usize::MAX {
                    for y in 0..k {
                        v[i * k + y] = if y == cellof[x as usize] { conf } else { (1.0 - conf) / (k - 1) as f64 };
                    }
                }
            }
            log(p, &format!("group seed: {} largest groups ({:?} contacts)", p.mix_group_seed_n, order.iter().take(p.mix_group_seed_n).map(|&x| size[x]).collect::<Vec<_>>()));
            vec![v; n_restarts]
        }
        None => (0..n_restarts).map(|g| seed_prior(&contacts, &keep, k, p, g)).collect(),
    };
    // the seed sets the first stage's weights; the E-step prior keeps a fraction `mix_seed_keep` of it
    let seed: Vec<Vec<f64>> = nu.clone();
    for v in nu.iter_mut() {
        for x in v.iter_mut() {
            *x = p.mix_seed_keep * *x + (1.0 - p.mix_seed_keep) / k as f64;
        }
    }
    let mut lambda: Vec<Vec<f64>> = vec![vec![1.0 / k as f64; k]; n_restarts];
    let mut em_state: Vec<(f64, f64)> = vec![(p.robust_eps, p.robust_s); n_restarts];
    let mut last_post: Vec<Vec<Option<Vec<f64>>>> = vec![vec![None; contacts.len()]; n_restarts];
    let mut last_rtrue: Vec<Vec<f64>> = vec![vec![f64::NAN; contacts.len()]; n_restarts];
    let mut last_ll: Vec<f64> = vec![f64::NEG_INFINITY; n_restarts];
    let mut groups_alive: Vec<usize> = (0..n_restarts).collect();
    let mut committed: Vec<Option<usize>> = vec![None; contacts.len()];
    let mut dropped = vec![false; contacts.len()];
    let mut sizes = p.particle_sizes.clone();
    sizes.extend(std::iter::repeat_n(last, p.robust_refine));
    let mut prev: Option<Structure> = None;
    let mut stages = vec![];
    let mut snapshots: Vec<Vec<Vec<V3>>> = vec![];
    let mut restart_log: Vec<(usize, Vec<f64>)> = vec![];
    for (stage, &ps) in sizes.iter().enumerate() {
        let ts = Instant::now();
        let ng = groups_alive.len();
        let per_group = k * m;
        // re-admission of dropped contacts
        if p.mix_readmit_stage >= 1 && stage as i64 == p.mix_readmit_stage {
            let n_re = dropped.iter().filter(|&&x| x).count();
            for (i, d) in dropped.iter_mut().enumerate() {
                if *d {
                    keep[i] = true;
                    *d = false;
                }
            }
            log(p, &format!("stage {}: {n_re} contacts re-admitted", stage + 1));
        }
        // staged commitment by the posteriors of the (single) surviving group
        if p.mix_commit > 0.0 && ng == 1 && p.mix_commit_stage >= 1 && stage as i64 >= p.mix_commit_stage {
            let g = groups_alive[0];
            let (mut nc, mut nd) = (0usize, 0usize);
            for i in 0..contacts.len() {
                if !keep[i] || committed[i].is_some() {
                    continue;
                }
                if let Some(pp) = &last_post[g][i] {
                    let (bx, bv) = pp.iter().enumerate().fold((0, f64::NEG_INFINITY), |a, (x, &v)| if v > a.1 { (x, v) } else { a });
                    if bv >= p.mix_commit {
                        committed[i] = Some(bx);
                        nc += 1;
                    } else if p.mix_commit_drop && (stage as i64) == p.mix_commit_stage {
                        keep[i] = false;
                        dropped[i] = true;
                        nd += 1;
                    }
                }
            }
            for i in 0..contacts.len() {
                if let Some(x) = committed[i] {
                    for gg in 0..n_restarts {
                        for y in 0..k {
                            nu[gg][i * k + y] = if y == x { 1.0 } else { 0.0 };
                        }
                    }
                }
            }
            log(p, &format!("stage {}: {nc} contacts committed (>= {}), {nd} dropped", stage + 1, p.mix_commit));
        }
        // violated contacts: closest cell (replicate-mean distance) >= threshold, before stages < 0.5 Mb
        if p.robust_remove_violated && stage > 0 && ps < 0.5e6 {
            if let Some(pr) = prev.as_ref() {
                let thr = p.violated_threshold_2017;
                let nm_tot = pr.n_models();
                let ok: Vec<bool> = contacts
                    .par_iter()
                    .zip(keep.par_iter())
                    .map(|(c, &kp)| {
                        if !kp {
                            return false;
                        }
                        let d = contact_dists(c, pr);
                        (0..nm_tot / m).map(|cell| d[cell * m..(cell + 1) * m].iter().sum::<f64>() / m as f64).fold(f64::INFINITY, f64::min) < thr
                    })
                    .collect();
                keep = ok;
                log(p, &format!("contacts after removing violated = {}", keep.iter().filter(|&&x| x).count()));
            }
        }
        let psi = ps as i32 as i64;
        let d = base_dict(&contacts, &keep);
        let grid = calc_particles(&d, &chroms, psi);
        let mut st = Structure::new(&grid);
        let n = st.n_particles();
        let n_models_tot = ng * per_group;
        st.coords = start_coords(&st, n_models_tot, prev.as_ref(), p, stage);
        let bins = bin_contacts(&contacts, &keep, &st);
        let backbone = backbone_restraints(&st, psi, p.backbone_dist_lower, p.backbone_dist_upper);
        let nbb = backbone.len();
        let reweight = stage >= p.robust_start_stage && bins.n() > 0;
        let refine_pass = stage >= p.particle_sizes.len();
        let n_temp = if refine_pass && p.robust_refine_temp_steps > 0 {
            p.robust_refine_temp_steps
        } else {
            p.robust_temp_steps_for(stage.min(p.particle_sizes.len() - 1))
        };
        let t_start = if refine_pass && p.robust_refine_temp_start > 0.0 { p.robust_refine_temp_start } else { p.temp_start };
        let schedule = anneal_schedule(t_start, p.temp_end, n_temp, 1.0);
        let dyn_steps = p.robust_dyn_steps_for(stage.min(p.particle_sizes.len() - 1));
        let parts = split_schedule(schedule.len(), if reweight { p.robust_segments } else { 1 });
        let odds: Vec<f64> = odds_all.clone();
        let t_prep = ts.elapsed().as_secs_f64();
        log(
            p,
            &format!(
                "stage {} ({} kb): {} particles, {} contacts in {} bins, {} groups x {k} cells x {m} models",
                stage + 1,
                ps / 1e3,
                n,
                bins.n_contacts(),
                bins.n(),
                ng
            ),
        );
        let td = Instant::now();
        let mut coords = std::mem::take(&mut st.coords);
        let mut em_logs = vec![];
        let mut t_em = 0.0;
        let mut f_dist = p.dist_force_const;
        for (seg, range) in parts.iter().enumerate() {
            // weights of every model: per group, per cell
            let mut rows: Vec<Vec<f64>> = Vec::with_capacity(n_models_tot);
            let mut counts = vec![0.0f64; bins.n()];
            for (gi, &g) in groups_alive.iter().enumerate() {
                let w = if reweight {
                    let te = Instant::now();
                    let gc = &coords[gi * per_group..(gi + 1) * per_group];
                    let data = EmData::new(gc, &bins.pairs, &vec![1u32; bins.n()], &kern_reach, s_max, p.robust_pair_sample);
                    let (eps, s) = em_state[g];
                    let res = em_update_mix(&data, &bins, &odds, &nu[g], &lambda[g], k, m, &kern, p, eps, s, groups.as_deref());
                    em_state[g] = (res.eps, res.s);
                    lambda[g] = res.lambda.clone();
                    last_ll[g] = res.log.loglik;
                    // posteriors per contact-list index
                    let mut q = 0usize;
                    for b in 0..bins.n() {
                        for &c in &bins.contacts[bins.off[b] as usize..bins.off[b + 1] as usize] {
                            last_post[g][c as usize] = Some(res.post[q * k..(q + 1) * k].to_vec());
                            last_rtrue[g][c as usize] = res.r_true[q];
                            q += 1;
                        }
                    }
                    let cb = {
                        let (rt, po) = (&res.r_true, &res.post);
                        // contact c -> its slot q in bin order
                        let mut slot = vec![usize::MAX; contacts.len()];
                        for (q, &c) in bins.contacts.iter().enumerate() {
                            slot[c as usize] = q;
                        }
                        bin_counts(&bins, k, &|c, x| {
                            let q = slot[c];
                            rt[q] * po[q * k + x]
                        })
                    };
                    for (a, b) in counts.iter_mut().zip(&cb) {
                        *a = a.max(*b);
                    }
                    if p.mix_prior_mode == "posterior" {
                        // the posterior of this update (tempered, floored) is the prior of the next one
                        for (i, pp) in last_post[g].iter().enumerate() {
                            if let Some(pp) = pp {
                                let t: Vec<f64> = pp.iter().map(|x| x.max(1e-300).powf(p.mix_prior_temp)).collect();
                                let tot: f64 = t.iter().sum();
                                for x in 0..k {
                                    nu[g][i * k + x] = (1.0 - p.mix_prior_floor) * t[x] / tot + p.mix_prior_floor / k as f64;
                                }
                            }
                        }
                    }
                    if let Some((edge_of, links)) = &tri_links {
                        // trans-triangle coupling: the prior of a trans contact is multiplied by the
                        // (pseudo-counted) mean posterior of the trans edges it closes triangles with
                        let ne = links.len();
                        let mut mean = vec![0.0f64; ne * k];
                        let mut cnt = vec![0u32; ne];
                        for (i, &e) in edge_of.iter().enumerate() {
                            if e >= 0 {
                                if let Some(pp) = &last_post[g][i] {
                                    for x in 0..k {
                                        mean[e as usize * k + x] += pp[x];
                                    }
                                    cnt[e as usize] += 1;
                                }
                            }
                        }
                        for e in 0..ne {
                            if cnt[e] > 0 {
                                for x in 0..k {
                                    mean[e * k + x] /= cnt[e] as f64;
                                }
                            }
                        }
                        for (i, &e) in edge_of.iter().enumerate() {
                            if e < 0 || links[e as usize].is_empty() {
                                continue;
                            }
                            let mut v = vec![p.mix_tri_pseudo / k as f64; k];
                            for &f in &links[e as usize] {
                                if cnt[f as usize] > 0 {
                                    for x in 0..k {
                                        v[x] += mean[f as usize * k + x];
                                    }
                                }
                            }
                            let tot_v: f64 = v.iter().sum();
                            let mut t = 0.0;
                            for x in 0..k {
                                let y = nu[g][i * k + x] * (v[x] / tot_v).powf(p.mix_tri_prior);
                                nu[g][i * k + x] = y;
                                t += y;
                            }
                            for x in 0..k {
                                nu[g][i * k + x] = if t > 0.0 { nu[g][i * k + x] / t } else { 1.0 / k as f64 };
                            }
                        }
                    }
                    if let Some(nb) = &nbr {
                        nu[g] = smooth_prior(nb, &last_post[g], k, p.mix_nbr_prior, p.mix_nbr_pseudo);
                        // committed contacts keep their cell
                        for i in 0..contacts.len() {
                            if let Some(x) = committed[i] {
                                for y in 0..k {
                                    nu[g][i * k + y] = if y == x { 1.0 } else { 0.0 };
                                }
                            }
                        }
                    }
                    let mut l = res.log;
                    l.segment = seg;
                    l.seconds = te.elapsed().as_secs_f64();
                    t_em += l.seconds;
                    log(
                        p,
                        &format!(
                            "  EM g{g} (part {seg}): eps {:.4} s {:.2} mean P(true) {:.3} cell-confident {:.3} lambda {:?} ll {:.4} ll0 {:.4} ({:.2} s)",
                            l.eps,
                            l.s,
                            l.mean_w,
                            l.phase_confident.unwrap_or(f64::NAN),
                            lambda[g].iter().map(|x| (x * 1000.0).round() / 1000.0).collect::<Vec<_>>(),
                            l.loglik,
                            l.ll_marginal.unwrap_or(f64::NAN),
                            l.seconds
                        ),
                    );
                    em_logs.push(l);
                    res.w
                } else {
                    let sg = &seed[g];
                    let cb = bin_counts(&bins, k, &|c, x| sg[c * k + x]);
                    for (a, b) in counts.iter_mut().zip(&cb) {
                        *a = a.max(*b);
                    }
                    prior_weights(&bins, &seed[g], k, p)
                };
                rows.extend(model_rows(&w, m));
            }
            let (rs, nb) = restraint_set(backbone.clone(), &bins, &counts, p);
            debug_assert_eq!(nb, nbb);
            let mut sys = System::new(n, vec![1.0; n], vec![1.0; n], &rs).with_form(RestraintForm::Weighted2017);
            set_weights(&mut sys, nb, &rows, n_models_tot);
            if p.robust_nc_scale > 0.0 {
                sys.nc = Some(NoContact { lambda: p.robust_nc_scale, d0: p.robust_nc_d0, s: p.robust_nc_s });
            }
            if p.mix_density_rho > 0.0 && stage as i64 >= p.mix_density_stage {
                sys.density = Some(crate::dynamics::DensityCap { kappa: p.mix_density_kappa, r: p.mix_density_r, rho_max: p.mix_density_rho });
            }
            let key = stage + 1000 * seg;
            f_dist = force_constant(p, &sys, nb, n);
            coords = engine.anneal(&sys, coords, &schedule[range.clone()], dyn_steps, f_dist, 1.0, key, p)?;
            // sampling at the end of the last stage
            if stage + 1 == sizes.len() && seg + 1 == parts.len() && p.robust_sample_temp > 0.0 && p.robust_sample_steps > 0 {
                let f_rep = schedule.last().map(|x| x.1).unwrap_or(1.0);
                let block = vec![(p.robust_sample_temp, f_rep); p.robust_sample_steps];
                let ds = if p.robust_sample_dyn_steps > 0 { p.robust_sample_dyn_steps } else { dyn_steps };
                for kk in 0..p.robust_sample_snapshots.max(1) {
                    coords = engine.anneal(&sys, coords, &block, ds, f_dist, 1.0, stage + 5000 + 1000 * kk, p)?;
                    snapshots.push(coords.clone());
                }
            }
        }
        centre(&mut coords);
        // restart selection: E-step likelihood on the end-of-stage structures, best group kept
        if ng > 1 && stage == p.mix_select_stage {
            let mut lls = vec![];
            for (gi, &g) in groups_alive.iter().enumerate() {
                let gc = &coords[gi * per_group..(gi + 1) * per_group];
                let data = EmData::new(gc, &bins.pairs, &vec![1u32; bins.n()], &kern_reach, s_max, p.robust_pair_sample);
                let (eps, s) = em_state[g];
                let res = em_update_mix(&data, &bins, &odds, &nu[g], &lambda[g], k, m, &kern, p, eps, s, groups.as_deref());
                lls.push(res.log.loglik);
            }
            let bi = (0..ng).max_by(|&a, &b| lls[a].partial_cmp(&lls[b]).unwrap()).unwrap();
            log(p, &format!("  restart selection after stage {}: log-likelihoods {:?} -> group {}", stage + 1, lls, groups_alive[bi]));
            restart_log.push((stage, lls));
            coords = coords[bi * per_group..(bi + 1) * per_group].to_vec();
            groups_alive = vec![groups_alive[bi]];
        }
        st.coords = coords;
        let t_dyn = td.elapsed().as_secs_f64() - t_em;
        log(p, &format!("stage {} done in {:.2} s ({:.2} s dynamics)", stage + 1, t_prep + t_dyn + t_em, t_dyn));
        stages.push(StageLog {
            stage,
            particle_size: ps,
            bead_size: 1.0,
            n_models: n_models_tot,
            n_particles: n,
            n_contacts: bins.n_contacts(),
            n_restraints: nbb + bins.n(),
            dist_force_const: f_dist,
            temp_steps: schedule.len(),
            dynamics_steps: dyn_steps,
            seconds_prepare: t_prep + t_em,
            seconds_dynamics: t_dyn,
            removed_models: vec![],
            device: engine.name(),
            rep_list_overflows: engine.overflow_stats().0,
            steps_without_repulsion: engine.overflow_stats().1,
            robust: em_logs,
        });
        prev = Some(st);
    }
    let mut st = prev.unwrap();
    let g = groups_alive[0];
    // final E-step over every input contact on the final structures
    let (eps, s) = em_state[g];
    // assignment kernel: EMber's kernel is flat inside d0 (every pair within the contact radius is
    // equally likely), which ties the cells on contacts that are close in both; the final
    // assignment uses `mix_assign_d0` (default 0: no flat region) so the closer cell wins
    let kk = Kernel { d0: p.mix_assign_d0, ..kern };
    let mut cell_probs = vec![f64::NAN; n_input * k];
    let mut contact_weights = vec![f64::NAN; n_input];
    {
        let gm: Vec<f64> = st
            .coords
            .iter()
            .map(|c| {
                let (h, np) = crate::robust::pair_histogram(c, kern_reach.reach(s_max), 0.02, p.robust_pair_sample);
                kernel_sum(&kk, &h, 0.02, np, s).max(1e-300)
            })
            .collect();
        let np = { let nn = st.n_particles() as f64; nn * (nn - 1.0) / 2.0 };
        let u = 1.0 / np.max(1.0);
        let lam = &lambda[g];
        let mut res: Vec<(usize, Vec<f64>, f64, Vec<f64>)> = contacts
            .par_iter()
            .enumerate()
            .map(|(i, c)| {
                let d = contact_dists(c, &st);
                let phi: Vec<f64> = (0..k).map(|x| (0..m).map(|r| kk.f(d[x * m + r], s) / gm[x * m + r]).sum::<f64>() / m as f64).collect();
                let pr: Vec<f64> = match committed[i] {
                    Some(x) => (0..k).map(|y| if y == x { 1.0 } else { 0.0 }).collect(),
                    None => vec![1.0; k],
                };
                let a: Vec<f64> = (0..k).map(|x| odds_all[i] * lam[x] * pr[x] * (1.0 - eps) * phi[x]).collect();
                let at: f64 = a.iter().sum();
                let post: Vec<f64> = if at > 0.0 { a.iter().map(|x| x / at).collect() } else { vec![1.0 / k as f64; k] };
                // log-evidence per cell (contact explained by the cell, or noise) for the groups
                let le: Vec<f64> = (0..k).map(|x| (odds_all[i] * (1.0 - eps) * phi[x] + eps * u).ln()).collect();
                (c.row as usize, post, if at > 0.0 { at / (at + eps * u) } else { 0.0 }, le)
            })
            .collect();
        if let Some(gr) = &groups {
            // grouped contacts share their group's posterior (contacts and rows are in the same order)
            let ng = gr.iter().filter(|&&x| x != u32::MAX).map(|&x| x as usize + 1).max().unwrap_or(0);
            let mut sums = vec![0.0f64; ng * k];
            for (i, r) in res.iter().enumerate() {
                if gr[i] != u32::MAX {
                    for x in 0..k {
                        sums[gr[i] as usize * k + x] += r.3[x];
                    }
                }
            }
            for gi in 0..ng {
                let row = &mut sums[gi * k..(gi + 1) * k];
                let mx = (0..k).map(|x| lam[x].max(1e-300).ln() + row[x]).fold(f64::NEG_INFINITY, f64::max);
                let mut tot = 0.0;
                for x in 0..k {
                    row[x] = (lam[x].max(1e-300).ln() + row[x] - mx).exp();
                    tot += row[x];
                }
                for x in 0..k {
                    row[x] /= tot;
                }
            }
            for (i, r) in res.iter_mut().enumerate() {
                if gr[i] != u32::MAX && committed[i].is_none() {
                    r.1 = sums[gr[i] as usize * k..(gr[i] as usize + 1) * k].to_vec();
                }
            }
        }
        for (r, post, pt, _) in res {
            cell_probs[r * k..(r + 1) * k].copy_from_slice(&post);
            contact_weights[r] = pt;
        }
    }
    if snapshots.len() > 1 {
        st.coords = snapshots.into_iter().flatten().collect();
        centre(&mut st.coords);
    }
    let nm = st.coords.len();
    if !restart_log.is_empty() {
        log(p, &format!("restarts: {restart_log:?}"));
    }
    Ok(Output {
        chroms: st.chroms,
        seq_pos: st.seq_pos,
        coords: st.coords,
        model_rmsds: vec![f64::NAN; nm],
        particle_size: last,
        stages,
        seconds_total: t0.elapsed().as_secs_f64(),
        contact_weights,
        diploid: false,
        phase_probs: vec![],
        mix_cells: k,
        cell_probs,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pipeline::CpuEngine;

    /// k cells, each 3 chromosomes of random-walk chains (different per cell); contacts of each
    /// cell = pairs closer than a cutoff.  Returns pooled contacts and the cell of each.
    #[allow(clippy::type_complexity)]
    pub(crate) fn toy_pool(k: usize, seed: u64, n_draw: usize) -> (Vec<String>, Vec<u32>, Vec<i64>, Vec<u32>, Vec<i64>, Vec<usize>, Vec<Vec<Vec<V3>>>) {
        let mut rng = Rng::new(seed);
        let names: Vec<String> = ["chrA", "chrB", "chrC"].iter().map(|s| s.to_string()).collect();
        let step = 100_000i64;
        let nloc = 150usize;
        let mut cells = vec![];
        for _ in 0..k {
            let mut chains = vec![];
            for c in 0..3 {
                let mut q = [c as f64 * 3.0 + rng.normal(), rng.normal() * 3.0, rng.normal() * 3.0];
                let mut v = vec![];
                for _ in 0..nloc {
                    q = [q[0] + rng.normal() * 0.35, q[1] + rng.normal() * 0.35, q[2] + rng.normal() * 0.35];
                    v.push(q);
                }
                chains.push(v);
            }
            cells.push(chains);
        }
        let (mut ca, mut pa, mut cb, mut pb, mut origin) = (vec![], vec![], vec![], vec![], vec![]);
        for (s, chains) in cells.iter().enumerate() {
            for _ in 0..n_draw {
                let c1 = (rng.uniform() * 3.0) as usize;
                let c2 = if rng.uniform() < 0.85 { c1 } else { (rng.uniform() * 3.0) as usize };
                let i = (rng.uniform() * nloc as f64) as usize;
                let j = (rng.uniform() * nloc as f64) as usize;
                let (a, b) = (chains[c1][i], chains[c2][j]);
                let d2: f64 = (0..3).map(|x| (a[x] - b[x]).powi(2)).sum();
                if d2 < 0.8 {
                    ca.push(c1 as u32);
                    pa.push(i as i64 * step + 1 + (rng.uniform() * step as f64) as i64);
                    cb.push(c2 as u32);
                    pb.push(j as i64 * step + 1 + (rng.uniform() * step as f64) as i64);
                    origin.push(s);
                }
            }
        }
        (names, ca, pa, cb, pb, origin, cells)
    }

    fn pearson(a: &[f64], b: &[f64]) -> f64 {
        let n = a.len() as f64;
        let (ma, mb) = (a.iter().sum::<f64>() / n, b.iter().sum::<f64>() / n);
        let (mut sab, mut saa, mut sbb) = (0.0, 0.0, 0.0);
        for (x, y) in a.iter().zip(b) {
            sab += (x - ma) * (y - mb);
            saa += (x - ma).powi(2);
            sbb += (y - mb).powi(2);
        }
        sab / (saa * sbb).sqrt()
    }

    /// Whole-structure distance r of model `mi` vs truth cell `t` (particles at the loci).
    pub(crate) fn r_vs_truth(out: &Output, mi: usize, truth: &[Vec<V3>]) -> f64 {
        let mut dm = vec![];
        let mut dt = vec![];
        let mut idx = vec![];
        for (slot, &cid) in out.chroms.iter().enumerate() {
            let off: usize = out.seq_pos[..slot].iter().map(|v| v.len()).sum();
            for (q, &x) in out.seq_pos[slot].iter().enumerate() {
                let l = ((x - 1) / 100_000) as usize;
                if (x - 1) % 100_000 == 99_999 && l < truth[cid as usize].len() {
                    idx.push((off + q, truth[cid as usize][l], cid, l));
                }
            }
        }
        let x = &out.coords[mi];
        // long-range pairs only (>= 20 loci apart or trans): the polymer scaling alone gives a high
        // r on short-range pairs
        for a in 0..idx.len() {
            for b in a + 1..idx.len() {
                if idx[a].2 == idx[b].2 && idx[a].3.abs_diff(idx[b].3) < 20 {
                    continue;
                }
                let (pa, ta, _, _) = idx[a];
                let (pb, tb, _, _) = idx[b];
                dm.push((0..3).map(|z| (x[pa][z] - x[pb][z]).powi(2)).sum::<f64>().sqrt());
                dt.push((0..3).map(|z| (ta[z] - tb[z]).powi(2)).sum::<f64>().sqrt());
            }
        }
        pearson(&dm, &dt)
    }

    #[test]
    fn seed_patch_is_spatially_coherent() {
        let (names, ca, pa, cb, pb, _, _) = toy_pool(2, 3, 30_000);
        let n = ca.len();
        let amb: Vec<i64> = (1..=n as i64).collect();
        let act = vec![true; n];
        let input = Input { names: &names, chr_a: &ca, pos_a: &pa, chr_b: &cb, pos_b: &pb, ambig: &amb, active: &act, prior_lr: None, dip: None };
        let cs = prepare_contacts(&input);
        let p = Params { mix_seed: "patch".into(), mix_seed_patch: 50.0, mix_seed_min_sep: 1_000_000, ..Default::default() };
        let nu = seed_prior(&cs, &vec![true; n], 3, &p, 0);
        let mut hard = 0;
        for (i, c) in cs.iter().enumerate() {
            let row = &nu[i * 3..i * 3 + 3];
            assert!((row.iter().sum::<f64>() - 1.0).abs() < 1e-12);
            if c.sep() < 1_000_000 {
                assert!(row.iter().all(|&x| (x - 1.0 / 3.0).abs() < 1e-12));
            } else {
                assert!(row.contains(&1.0));
                hard += 1;
            }
        }
        assert!(hard > 0);
        // different restarts give different seeds
        let nu2 = seed_prior(&cs, &vec![true; n], 3, &p, 1);
        assert_ne!(nu, nu2);
    }

    #[test]
    fn em_assigns_contacts_to_the_cell_that_fits() {
        // two fixed "cells": the same 3 chains in different random folds; contacts from each
        let (names, ca, pa, cb, pb, origin, cells) = toy_pool(2, 7, 40_000);
        let _ = names;
        let n = ca.len();
        // structure = truth: one model per cell, particles at the loci (100 kb grid)
        let mut grid = BTreeMap::new();
        for c in 0..3u32 {
            grid.insert(c, (1..=150).map(|x| x as i64 * 100_000).collect::<Vec<i64>>());
        }
        let mut st = Structure::new(&grid);
        // the toy walks have step 0.35 (a 100 kb particle ~ radius 1 in model units: scale by 1/0.35)
        st.coords = cells.iter().map(|ch| ch.iter().flatten().map(|q| [q[0] / 0.35, q[1] / 0.35, q[2] / 0.35]).collect()).collect();
        let cs: Vec<MixContact> = (0..n)
            .map(|i| {
                let (mut a, mut x, mut b, mut y) = (ca[i], pa[i], cb[i], pb[i]);
                if (a, x) > (b, y) {
                    std::mem::swap(&mut a, &mut b);
                    std::mem::swap(&mut x, &mut y);
                }
                MixContact { ca: a, pa: x, cb: b, pb: y, row: i as u32 }
            })
            .collect();
        let keep = vec![true; n];
        let bins = bin_contacts(&cs, &keep, &st);
        let p = Params { protocol: "robust".into(), mix_cells: 2, ..Default::default() };
        let kern = Kernel::from_params(&p);
        let data = EmData::new(&st.coords, &bins.pairs, &vec![1; bins.n()], &kern, 6.0, 0);
        let nu = vec![0.5; n * 2];
        let res = em_update_mix(&data, &bins, &vec![1.0; n], &nu, &[0.5, 0.5], 2, 1, &kern, &p, 0.1, 1.5, None);
        // accuracy over long-range contacts (> 2 Mb or trans), where the cells differ
        let (mut right, mut tot) = (0usize, 0usize);
        for (q, &c) in bins.contacts.iter().enumerate() {
            let cc = &cs[c as usize];
            if cc.sep() < 2_000_000 {
                continue;
            }
            tot += 1;
            let best = if res.post[q * 2] > res.post[q * 2 + 1] { 0 } else { 1 };
            right += (best == origin[c as usize]) as usize;
        }
        let acc = right as f64 / tot as f64;
        eprintln!("E-step on the true structures: long-range assignment accuracy {acc:.3} ({tot} contacts)");
        assert!(acc > 0.9, "{acc}");
    }

    /// End to end on the toy: two cells pooled; the pipeline runs (restarts, selection, final
    /// E-step over every contact), and from a seed that is right for 75 % of the contacts (the
    /// other 25 % random) the posterior-accumulating EM keeps the per-cell structures and the
    /// long-range assignments well above chance.  (From an uninformative seed the method does not
    /// find the cells: the symmetry-breaking problem of `mix_devlog.md`.)
    #[test]
    fn deconvolves_two_toy_cells() {
        let (names, ca, pa, cb, pb, origin, cells) = toy_pool(2, 11, 40_000);
        let n = ca.len();
        let amb: Vec<i64> = (1..=n as i64).collect();
        let act = vec![true; n];
        let input = Input { names: &names, chr_a: &ca, pos_a: &pa, chr_b: &cb, pos_b: &pb, ambig: &amb, active: &act, prior_lr: None, dip: None };
        let p = Params {
            protocol: "robust".into(),
            mix_cells: 2,
            mix_restarts: 2,
            mix_select_stage: 1,
            particle_sizes: vec![4e6, 1e6, 4e5, 2e5],
            n_models: 2,
            seed: 3,
            robust_temp_steps: vec![60],
            robust_dynamics_steps: vec![50],
            n_threads: 2,
            ..Default::default()
        };
        let mut eng = CpuEngine::new(2).unwrap();
        // uninformative seed: runs end to end
        let out0 = calc_genome_structure(&input, &p, &mut eng).unwrap();
        assert_eq!(out0.coords.len(), 4);
        for i in 0..n {
            let s: f64 = out0.cell_probs[2 * i..2 * i + 2].iter().sum();
            assert!((s - 1.0).abs() < 1e-9);
        }
        let mut rng = Rng::new(5);
        let mut prior = vec![0.0; 2 * n];
        for i in 0..n {
            let c = if rng.uniform() < 0.5 { (rng.uniform() * 2.0) as usize } else { origin[i] };
            prior[2 * i + c] = 1.0;
        }
        let p = Params { mix_restarts: 1, mix_seed_keep: 0.95, mix_prior_mode: "posterior".into(), mix_prior_floor: 0.0, ..p };
        let out = calc_with_prior(&input, &p, &mut eng, Some(&prior)).unwrap();
        assert_eq!(out.mix_cells, 2);
        assert_eq!(out.coords.len(), 4);
        assert_eq!(out.cell_probs.len(), 2 * n);
        // matching: model 0 of cell 0 vs truths
        let r = |mi: usize, t: usize| r_vs_truth(&out, mi, &cells[t]);
        let (a, b) = (r(0, 0) + r(2, 1), r(0, 1) + r(2, 0));
        let perm = if a >= b { [0usize, 1] } else { [1, 0] };
        let r_cells = [r(0, perm[0]), r(2, perm[1])];
        let (mut right, mut tot) = (0usize, 0usize);
        for i in 0..n {
            let sep = if ca[i] == cb[i] { (pa[i] - pb[i]).abs() } else { i64::MAX };
            if sep < 2_000_000 {
                continue;
            }
            tot += 1;
            let best = if out.cell_probs[2 * i] >= out.cell_probs[2 * i + 1] { 0 } else { 1 };
            right += (perm[best] == origin[i]) as usize;
        }
        // label-invariant accuracy (the r matching is weak on these toys: truth vs truth r ~ 0.4)
        let acc = (right as f64 / tot as f64).max(1.0 - right as f64 / tot as f64);
        eprintln!("toy k = 2: per-cell r {r_cells:.3?}, long-range assignment accuracy {acc:.3} ({tot})");
        assert!(r_cells[0] > 0.5 && r_cells[1] > 0.5, "{r_cells:?}");
        assert!(acc > 0.7, "{acc}");
    }

    /// Diagnostics on the toy (run by hand: `cargo test --release --lib mix::tests::diag -- --ignored --nocapture`).
    /// `UCHROM_MIX_DIAG` = JSON of Params overrides for the mix runs.
    #[test]
    #[ignore]
    fn diag_toy() {
        let k: usize = std::env::var("UCHROM_MIX_K").ok().and_then(|v| v.parse().ok()).unwrap_or(2);
        let seed: u64 = std::env::var("UCHROM_MIX_TOYSEED").ok().and_then(|v| v.parse().ok()).unwrap_or(11);
        let (names, ca, pa, cb, pb, origin, cells) = toy_pool(k, seed, 40_000);
        let n = ca.len();
        let amb: Vec<i64> = (1..=n as i64).collect();
        let act = vec![true; n];
        let base = Params {
            protocol: "robust".into(),
            particle_sizes: vec![4e6, 1e6, 4e5, 2e5],
            n_models: 2,
            seed: 3,
            robust_temp_steps: vec![60],
            robust_dynamics_steps: vec![50],
            n_threads: 8,
            ..Default::default()
        };
        let mut eng = CpuEngine::new(8).unwrap();
        // oracle: each cell alone
        for t in 0..k {
            let idx: Vec<usize> = (0..n).filter(|&i| origin[i] == t).collect();
            let sel = |v: &[u32]| idx.iter().map(|&i| v[i]).collect::<Vec<u32>>();
            let sel64 = |v: &[i64]| idx.iter().map(|&i| v[i]).collect::<Vec<i64>>();
            let (a, b, c, d) = (sel(&ca), sel64(&pa), sel(&cb), sel64(&pb));
            let am: Vec<i64> = (1..=idx.len() as i64).collect();
            let ac = vec![true; idx.len()];
            let inp = Input { names: &names, chr_a: &a, pos_a: &b, chr_b: &c, pos_b: &d, ambig: &am, active: &ac, prior_lr: None, dip: None };
            let out = crate::robust::calc_genome_structure(&inp, &base, &mut eng).unwrap();
            let ll = out.stages.last().and_then(|s| s.robust.last()).map(|l| l.loglik).unwrap_or(f64::NAN);
            eprintln!("oracle cell {t}: r {:.3} ({} contacts, ll {ll:.3})", r_vs_truth(&out, 0, &cells[t]), idx.len());
        }
        {
            // truth vs truth, the same long-range pairs (sampled)
            let flat = |t: usize| -> Vec<(V3, usize, usize)> {
                let mut v = vec![];
                for (c, ch) in cells[t].iter().enumerate() {
                    for (l, q) in ch.iter().enumerate() {
                        if l % 2 == 1 {
                            v.push((*q, c, l));
                        }
                    }
                }
                v
            };
            for t in 1..k {
                let (a, b) = (flat(0), flat(t));
                let (mut x, mut y) = (vec![], vec![]);
                for i in 0..a.len() {
                    for j in i + 1..a.len() {
                        if a[i].1 == a[j].1 && a[i].2.abs_diff(a[j].2) < 20 {
                            continue;
                        }
                        let dd = |u: V3, v: V3| (0..3).map(|z| (u[z] - v[z]).powi(2)).sum::<f64>().sqrt();
                        x.push(dd(a[i].0, a[j].0));
                        y.push(dd(b[i].0, b[j].0));
                    }
                }
                eprintln!("truth 0 vs truth {t}: long-range r {:.3}", pearson(&x, &y));
            }
        }
        let input = Input { names: &names, chr_a: &ca, pos_a: &pa, chr_b: &cb, pos_b: &pb, ambig: &amb, active: &act, prior_lr: None, dip: None };
        let naive = crate::robust::calc_genome_structure(&input, &base, &mut eng).unwrap();
        eprintln!("naive (pooled as one cell): r vs truths {:?}", (0..k).map(|t| (r_vs_truth(&naive, 0, &cells[t]) * 1000.0).round() / 1000.0).collect::<Vec<_>>());
        let extra: serde_json::Value = serde_json::from_str(&std::env::var("UCHROM_MIX_DIAG").unwrap_or("{}".into())).unwrap();
        let mut pj = serde_json::to_value(&Params { mix_cells: k, ..base.clone() }).unwrap();
        for (kk, v) in extra.as_object().unwrap() {
            pj[kk] = v.clone();
        }
        let pm: Params = serde_json::from_value(pj).unwrap();
        let report = |label: &str, out: &Output| {
            let mm = pm.n_models;
            // r matrix (recovered cell x truth), greedy-optimal for small k by permutations
            let rm: Vec<Vec<f64>> = (0..k).map(|s| (0..k).map(|t| r_vs_truth(out, s * mm, &cells[t])).collect()).collect();
            let mut perm: Vec<usize> = (0..k).collect();
            let mut best = (f64::NEG_INFINITY, perm.clone());
            fn permute(v: &mut Vec<usize>, l: usize, f: &mut dyn FnMut(&[usize])) {
                if l == v.len() {
                    f(v);
                    return;
                }
                for i in l..v.len() {
                    v.swap(l, i);
                    permute(v, l + 1, f);
                    v.swap(l, i);
                }
            }
            permute(&mut perm, 0, &mut |q: &[usize]| {
                let sc: f64 = (0..k).map(|s| rm[s][q[s]]).sum();
                if sc > best.0 {
                    best = (sc, q.to_vec());
                }
            });
            let q = best.1;
            let (mut right, mut tot, mut right_all) = (0usize, 0usize, 0usize);
            for i in 0..n {
                let pr = &out.cell_probs[i * k..(i + 1) * k];
                let bx = (0..k).max_by(|&a, &b| pr[a].partial_cmp(&pr[b]).unwrap()).unwrap();
                right_all += (q[bx] == origin[i]) as usize;
                let sep = if ca[i] == cb[i] { (pa[i] - pb[i]).abs() } else { i64::MAX };
                if sep >= 2_000_000 {
                    tot += 1;
                    right += (q[bx] == origin[i]) as usize;
                }
            }
            let mut conf = vec![vec![0usize; k]; k];
            for i in 0..n {
                let sep = if ca[i] == cb[i] { (pa[i] - pb[i]).abs() } else { i64::MAX };
                if sep < 2_000_000 {
                    continue;
                }
                let pr = &out.cell_probs[i * k..(i + 1) * k];
                let bx = (0..k).max_by(|&a, &b| pr[a].partial_cmp(&pr[b]).unwrap()).unwrap();
                conf[bx][origin[i]] += 1;
            }
            eprintln!("{label}: recovered x true (long-range) {conf:?}, matching {q:?}");
            let ll = out.stages.last().and_then(|s| s.robust.last()).map(|l| l.loglik).unwrap_or(f64::NAN);
            eprintln!(
                "{label}: matched r {:?} (mean {:.3}), accuracy long-range {:.3} all {:.3}, final ll {ll:.4}",
                (0..k).map(|s| (rm[s][q[s]] * 1000.0).round() / 1000.0).collect::<Vec<_>>(),
                (0..k).map(|s| rm[s][q[s]]).sum::<f64>() / k as f64,
                right as f64 / tot as f64,
                right_all as f64 / n as f64
            );
        };
        // oracle seed: the true cell of every contact at the first stage, EM afterwards
        let mut prior = vec![0.0; n * k];
        for i in 0..n {
            prior[i * k + origin[i]] = 1.0;
        }
        let out = calc_with_prior(&input, &pm, &mut eng, Some(&prior)).unwrap();
        report("mix, oracle seed", &out);
        let out = calc_genome_structure(&input, &pm, &mut eng).unwrap();
        report("mix", &out);
    }
}
